// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
        // owner starts at address(0); claim ownership from address(0) so the
        // test contract can later exercise transferOwnership.
        vm.prank(address(0));
        c.transferOwnership(address(this));
    }

    function testFuzz_property(address newOwner) public {
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}
